-- PostgreSQL schema corresponding to the current SQLite database.
CREATE TABLE schools(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE semesters(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,cutoff_at TEXT NOT NULL,rules_version TEXT NOT NULL);
CREATE TABLE organizations(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','admin','partner')),school_id INTEGER REFERENCES schools(id),organization_id INTEGER REFERENCES organizations(id),name TEXT);
CREATE TABLE enrollments(user_id INTEGER NOT NULL REFERENCES users(id),semester_id INTEGER NOT NULL REFERENCES semesters(id),school_id INTEGER NOT NULL REFERENCES schools(id),PRIMARY KEY(user_id,semester_id));
CREATE TABLE missions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id),semester_id INTEGER NOT NULL REFERENCES semesters(id),title TEXT NOT NULL,notice TEXT NOT NULL,source_url TEXT NOT NULL,apply_url TEXT NOT NULL,eligibility TEXT NOT NULL,application_period TEXT NOT NULL,completion_policy TEXT NOT NULL,weights TEXT NOT NULL,rules_version TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('open','closed')),is_demo INTEGER NOT NULL DEFAULT 0,application_start TEXT,application_end TEXT,archived_at TEXT,created_by INTEGER REFERENCES users(id),contribution_value DOUBLE PRECISION NOT NULL DEFAULT 1,application_note TEXT NOT NULL DEFAULT '');
CREATE TABLE events(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mission_id INTEGER NOT NULL REFERENCES missions(id),user_id INTEGER NOT NULL REFERENCES users(id),event_type TEXT NOT NULL CHECK(event_type IN ('view','click')),created_at TEXT DEFAULT (CURRENT_TIMESTAMP::text));
CREATE TABLE verifications(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mission_id INTEGER NOT NULL REFERENCES missions(id),user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL,source TEXT,external_record_id TEXT,reviewed_by INTEGER REFERENCES users(id),updated_at TEXT DEFAULT (CURRENT_TIMESTAMP::text),UNIQUE(mission_id,user_id));
CREATE UNIQUE INDEX unique_external_record ON verifications(external_record_id) WHERE external_record_id IS NOT NULL AND external_record_id != '';
CREATE TABLE audit_log(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,mission_id INTEGER,user_id INTEGER,detail TEXT,created_at TEXT DEFAULT (CURRENT_TIMESTAMP::text));
CREATE TABLE application_claims(mission_id INTEGER NOT NULL REFERENCES missions(id),user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),PRIMARY KEY(mission_id,user_id));
CREATE TABLE school_semester_population(school_id INTEGER NOT NULL REFERENCES schools(id),semester_id INTEGER NOT NULL REFERENCES semesters(id),student_count INTEGER NOT NULL CHECK(student_count>0),reference_year INTEGER NOT NULL,source_url TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),updated_by INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(school_id,semester_id));
CREATE TABLE automatic_mission_sources(source_kind TEXT NOT NULL,external_id TEXT NOT NULL,mission_id INTEGER NOT NULL UNIQUE REFERENCES missions(id),verified_until BIGINT NOT NULL,PRIMARY KEY(source_kind,external_id));
CREATE TABLE automation_status(id INTEGER PRIMARY KEY CHECK(id=1),last_attempt BIGINT,message TEXT,created_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE automation_candidates(url TEXT PRIMARY KEY,title TEXT,result TEXT NOT NULL,checked_at BIGINT NOT NULL);
CREATE TABLE school_population_automation(id INTEGER PRIMARY KEY CHECK(id=1),last_attempt BIGINT,last_success BIGINT,message TEXT);
CREATE TABLE school_population_latest(school_id INTEGER PRIMARY KEY REFERENCES schools(id),student_count INTEGER NOT NULL,reference_year INTEGER NOT NULL,source_url TEXT NOT NULL,evidence TEXT NOT NULL,updated_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE app_migrations(name TEXT PRIMARY KEY);
CREATE TABLE mission_category_history(mission_id INTEGER PRIMARY KEY REFERENCES missions(id),original_weights TEXT NOT NULL,new_weights TEXT NOT NULL,changed_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text));
